def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    if n == 1:
        return [0]
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # Iterative BFS order from root 0
    parent = [-1] * n
    order = [0]
    parent[0] = -2
    for u in order:
        for v in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                order.append(v)
    parent[0] = -1

    # Subtree weight sums
    sub = w[:]
    for u in reversed(order):
        p = parent[u]
        if p >= 0:
            sub[p] += sub[u]
    total = sub[0]

    # Depth and S(0)
    depth = [0] * n
    for u in order:
        p = parent[u]
        if p >= 0:
            depth[u] = depth[p] + 1
    res = [0] * n
    res[0] = sum(w[u] * depth[u] for u in range(n))

    # Reroot: S(child) = S(parent) + total - 2 * sub[child]
    for u in order:
        p = parent[u]
        if p >= 0:
            res[u] = res[p] + total - 2 * sub[u]
    return res
